const execution = $json.execution || {};
const workflow = $json.workflow || {};
return [{
  json: {
    error_id: `err_${Date.now()}`,
    workflow_name: workflow.name || 'unknown',
    workflow_id: workflow.id || 'unknown',
    execution_id: execution.id || 'unknown',
    last_node_executed: execution.lastNodeExecuted || 'unknown',
    error_message: execution.error?.message || $json.error?.message || 'Unknown workflow error',
    input_summary: execution.mode ? `mode=${execution.mode}` : 'summary unavailable',
    captured_at: new Date().toISOString()
  }
}];

const input = $json || {};

const TRANSIENT_PROVIDER_ERRORS = new Set([
  'timeout',
  'provider_429',
  'provider_5xx',
  'provider_timeout',
  'provider_aborted',
  'provider_output_truncated',
]);
const REVIEW_ERRORS = new Set([
  'approval_blocked',
  'provider_401',
  'provider_error',
  'provider_invalid_json',
  'provider_response_missing',
  'malformed_evidence',
  'empty_response',
  'unknown_error',
  'unknown',
]);
const STOP_ERRORS = new Set([
  'forbidden_action',
  'input_error',
  'workflow_config_error',
  'safety_blocked',
]);
const KNOWN_ERROR_CLASSES = new Set([
  ...TRANSIENT_PROVIDER_ERRORS,
  ...REVIEW_ERRORS,
  ...STOP_ERRORS,
]);

function safeId(prefix, value) {
  const source = String(value || Date.now()).replace(/[^A-Za-z0-9_-]/g, '_').slice(0, 80);
  return prefix + '_' + (source || Date.now());
}

function clampInteger(value, fallback, min, max) {
  const number = Number(value);
  if (!Number.isFinite(number)) return fallback;
  return Math.max(min, Math.min(max, Math.floor(number)));
}

function classifyError(value) {
  const explicitClass = String(
    value.error_class
    || value.provider_error?.class
    || value.provider_error?.code
    || value.error?.class
    || value.error?.code
    || ''
  ).toLowerCase();
  const message = [
    value.error_message,
    value.provider_error?.message,
    value.error?.message,
    value.summary,
    value.status,
  ].filter(Boolean).join(' ').toLowerCase();
  const node = String(value.last_node_executed || '').toLowerCase();

  if (KNOWN_ERROR_CLASSES.has(explicitClass)) return explicitClass;
  if (message.includes('safety_blocked') || message.includes('safety blocked')) return 'safety_blocked';
  if (message.includes('provider_401') || message.includes(' 401') || message.includes('unauthorized')) return 'provider_401';
  if (message.includes('provider_429') || message.includes(' 429') || message.includes('rate limit')) return 'provider_429';
  if (message.includes('provider_5xx') || /\b5\d\d\b/.test(message) || message.includes('server error')) return 'provider_5xx';
  if (message.includes('unknown_error')) return 'unknown_error';
  if (message.includes('forbidden')) return 'forbidden_action';
  if (message.includes('approval') || message.includes('human')) return 'approval_blocked';
  if (message.includes('truncated') || message.includes('finish_reason=length')) return 'provider_output_truncated';
  if (message.includes('aborted') || message.includes('socket')) return 'provider_aborted';
  if (message.includes('timeout') || message.includes('timed out')) return 'provider_timeout';
  if (message.includes('invalid json') || message.includes('parse')) return 'provider_invalid_json';
  if (message.includes('missing') && message.includes('response')) return 'provider_response_missing';
  if (node.includes('http request') || node.includes('provider')) return 'provider_error';
  if (message.includes('validation') || message.includes('invalid payload')) return 'input_error';
  if (message.includes('credential') || message.includes('workflow')) return 'workflow_config_error';
  return 'unknown';
}

function buildDecision(errorClass, retryCount, maxRetries) {
  if (STOP_ERRORS.has(errorClass)) {
    return {
      decision: 'stop',
      next_action: 'stop_run',
      stop_conditions: [errorClass + '_is_not_recoverable_by_retry'],
    };
  }

  if (TRANSIENT_PROVIDER_ERRORS.has(errorClass)) {
    if (retryCount < maxRetries) {
      return {
        decision: 'retry',
        next_action: 'retry_provider_readonly',
        stop_conditions: ['retry_count_reaches_' + maxRetries],
      };
    }

    return {
      decision: 'stop',
      next_action: 'stop_run',
      stop_conditions: ['retry_budget_exhausted'],
    };
  }

  if (REVIEW_ERRORS.has(errorClass)) {
    return {
      decision: 'needs_review',
      next_action: 'manual_review',
      stop_conditions: ['human_review_required_before_retry'],
    };
  }

  return {
    decision: 'needs_review',
    next_action: 'manual_review',
    stop_conditions: ['unclassified_error_requires_review'],
  };
}

function reasonFor(errorClass, decision, retryCount, maxRetries) {
  if (decision === 'retry') {
    return errorClass + ' appears transient; retry the read-only provider path only after human review within the bounded retry budget (' + retryCount + '/' + maxRetries + ').';
  }
  if (decision === 'stop') {
    if (retryCount >= maxRetries && TRANSIENT_PROVIDER_ERRORS.has(errorClass)) {
      return errorClass + ' reached the retry limit (' + retryCount + '/' + maxRetries + '); stop the run and keep it reviewable.';
    }
    return errorClass + ' should not be retried automatically; stop the run and preserve the safety boundary.';
  }
  return errorClass + ' requires human review before another attempt or follow-up action.';
}

const maxRetries = clampInteger(input.max_retries, 2, 0, 3);
const retryCount = clampInteger(input.retry_count, 0, 0, 3);
const timeoutMinutes = clampInteger(input.timeout_minutes, 15, 1, 30);
const errorClass = classifyError(input);
const decision = buildDecision(errorClass, retryCount, maxRetries);
const recoveryPolicy = {
  policy_version: 'v0.17-local-recovery-policy',
  run_id: input.run_id && /^gd_[A-Za-z0-9_-]+$/.test(input.run_id)
    ? input.run_id
    : safeId('gd_error', input.execution_id),
  task_id: input.task_id && /^task_[A-Za-z0-9_-]+$/.test(input.task_id)
    ? input.task_id
    : safeId('task_error', input.last_node_executed),
  error_class: errorClass,
  decision: decision.decision,
  next_action: decision.next_action,
  max_retries: maxRetries,
  retry_count: retryCount,
  timeout_minutes: timeoutMinutes,
  stop_conditions: decision.stop_conditions,
  reason: reasonFor(errorClass, decision.decision, retryCount, maxRetries),
  safety: {
    read_only: true,
    write_actions_enabled: false,
    requires_human_review: true,
    secrets_included: false,
  },
};

const recoveryAdvice = [
  'Review the failed execution in n8n execution history.',
  'Inspect the last executed node and sanitized input summary.',
  'Use recovery_policy.next_action as a recommendation only; do not retry automatically.',
  'Fix the workflow or payload, then rerun manually after human review.'
];

return [{
  json: {
    ...input,
    recovery_policy: recoveryPolicy,
    recovery_advice: recoveryAdvice,
    notification_markdown: [
      '# Goal-Driven Workflow Error',
      '',
      '- Workflow: ' + input.workflow_name,
      '- Execution: ' + input.execution_id,
      '- Last node: ' + input.last_node_executed,
      '- Error: ' + input.error_message,
      '',
      '## Recovery policy',
      '- Decision: ' + recoveryPolicy.decision,
      '- Next action: ' + recoveryPolicy.next_action,
      '- Error class: ' + recoveryPolicy.error_class,
      '- Human review required: yes',
      '',
      '## Recommended recovery',
      ...recoveryAdvice.map((item) => '- ' + item)
    ].join('\n')
  }
}];
